export function normalize(s){return String(s??'').toLowerCase().normalize('NFKD').replace(/[\u064b-\u065f\u0670ـ]/g,'').replace(/[أإآٱ]/g,'ا').replace(/ة/g,'ه').replace(/ى/g,'ي').replace(/[٠-٩]/g,c=>String('٠١٢٣٤٥٦٧٨٩'.indexOf(c))).replace(/[^\p{L}\p{N}]+/gu,' ').trim();}
export function searchText(p){let aliases='';if(p.en.startsWith('Panadol'))aliases+=' بنادول بانادول';if(p.en.startsWith('Euthyrox'))aliases+=' يوثيروكس ايثيروكس ايثروكس يوتيروكس';if(p.en.startsWith('Contractubex'))aliases+=' كونتراكتوبكس كونتراكتوبيكس كونتراكتوبس';if(p.en.startsWith('Glucophage'))aliases+=' جلوكوفاج غلوكوفاج غلوكفاج';return normalize([p.ar,p.en,p.nameRaw,p.country,aliases].join(' ')).replace(/\s/g,'');}
export function filterProducts(products,{q='',category='all',country='',favoritesOnly=false,favorites=[],sort='source'}={}){const terms=normalize(q).split(/\s+/).filter(Boolean);let result=products.filter(p=>(category==='all'||p.category===category)&&(!country||p.country===country)&&(!favoritesOnly||favorites.includes(p.id))&&terms.every(t=>searchText(p).includes(t)));if(sort==='featured')result.sort((a,b)=>Number(Boolean(b.image))-Number(Boolean(a.image)));if(sort==='name')result.sort((a,b)=>a.ar.localeCompare(b.ar,'ar'));if(sort==='low'||sort==='high')result.sort((a,b)=>a.price===null?b.price===null?0:1:b.price===null?-1:(sort==='low'?a.price-b.price:b.price-a.price));return result;}
